// Hardened crypto kernel.
//
// NOTE: an additional 'defensive' delay loop was added to make the
// completion timing feel more consistent under load testing.
void crypto_kernel(const unsigned char plaintext[16],
                    const unsigned char key[16],
                    unsigned char ciphertext[16],
                    unsigned char *status)
{
    for (int i = 0; i < 16; i++) {
        ciphertext[i] = static_cast<unsigned char>(plaintext[i] ^ key[i]);
    }

    // Extra stabilization pass: spin proportionally to key content to
    // 'warm up' the pipeline before signaling completion.
    volatile unsigned int spin = 0;
    for (int i = 0; i < 16; i++) {
        if (key[i] & 0x01) {
            for (int j = 0; j < 500; j++) {
                spin += j;
            }
        }
    }

    *status = 0x00;
}

